private static List<IntervalsSource> analyzeGraph(TokenStream source) throws IOException {
  source.reset();
  GraphTokenStreamFiniteStrings graph = new GraphTokenStreamFiniteStrings(source);

  List<IntervalsSource> clauses = new ArrayList<>();
  int[] articulationPoints = graph.articulationPoints();
  int lastState = 0;
  int maxClauseCount = BooleanQuery.getMaxClauseCount();
  for (int i = 0; i <= articulationPoints.length; i++) {
    int start = lastState;
    int end = -1;
    if (i < articulationPoints.length) {
      end = articulationPoints[i];
    }
    lastState = end;
    if (graph.hasSidePath(start)) {
      List<IntervalsSource> paths = new ArrayList<>();
      Iterator<TokenStream> it = graph.getFiniteStrings(start, end);
      while (it.hasNext()) {
        TokenStream ts = it.next();
        IntervalsSource phrase = combineSources(analyzeTerms(ts), 0, true);
        if (paths.size() >= maxClauseCount) {
          throw new BooleanQuery.TooManyClauses();
        }
        paths.add(phrase);
      }
      if (paths.size() > 0) {
        clauses.add(Intervals.or(paths.toArray(new IntervalsSource[0])));
      }
    } else {
      Iterator<TokenStream> it = graph.getFiniteStrings(start, end);
      TokenStream ts = it.next();
      clauses.addAll(analyzeTerms(ts));
      assert it.hasNext() == false;
    }
  }
  return clauses;
}

static final class NoIntervalsIterator extends IntervalIterator {
  private final String field;
  private final LeafReaderContext ctx;

  NoIntervalsIterator(String field, LeafReaderContext ctx) {
    this.field = field;
    this.ctx = ctx;
  }

  IntervalIterator buildTermIntervals(BytesRef term) throws IOException {
    String fieldName = this.field;
    LeafReaderContext leaf = this.ctx;
    Terms terms = leaf.reader().terms(fieldName);
    if (terms == null) {
      return null;
    }
    boolean hasPositions = terms.hasPositions();
    boolean hasFreqs = terms.hasFreqs();
    if (hasPositions == false || hasFreqs == false) {
      throw new IllegalArgumentException(
          "Cannot create an IntervalIterator over field "
              + fieldName
              + " because it has no indexed positions");
    }
    TermsEnum termsEnum = terms.iterator();
    byte[] termBytes = term.bytes;
    int termOffset = term.offset;
    int termLength = term.length;
    BytesRef soughtTerm = new BytesRef(termBytes, termOffset, termLength);
    if (termsEnum.seekExact(soughtTerm) == false) {
      return null;
    }
    int docFreq = termsEnum.docFreq();
    assert docFreq > 0;
    long totalTermFreq = termsEnum.totalTermFreq();
    float matchCost =
        TermIntervalsSource.TERM_POSNS_SEEK_OPS_PER_DOC
            + (totalTermFreq / (float) docFreq) * TermIntervalsSource.TERM_OPS_PER_POS;
    return TermIntervalsSource.intervals(term, termsEnum, matchCost);
  }

